"use client";

import * as React from "react";
import { pickChartHue } from "../../lib/chart-palette.js";
import { cn } from "../../lib/utils.js";

/**
 * Chord diagram. Nodes sit on a ring; ribbons inside the ring encode
 * weighted bidirectional relationships between them. Common for
 * trade flows, migration, hyperlink graphs, citation networks —
 * anywhere "A relates to B with weight w" matters at scale.
 *
 * Heavy peers: requires `d3-chord` (~3 KB gzip) and `d3-shape` (~6 KB
 * gzip, already in the artifacts/ family). The hex-core CLI's `add`
 * flow prompts before installing.
 *
 * @example
 * <Chord
 *   nodes={["A", "B", "C", "D"].map((id) => ({ id, label: id }))}
 *   matrix={[
 *     [0, 5, 8, 1],
 *     [3, 0, 2, 4],
 *     [6, 0, 0, 7],
 *     [2, 1, 9, 0],
 *   ]}
 * />
 */
export type ChordNode = {
	id: string;
	label: string;
};

/**
 * Payload fired to `onChordHover`. `sourceValue` is the i→j flow;
 * `targetValue` is the j→i flow. They differ for asymmetric matrices and
 * are equal for symmetric ones.
 */
export type ChordHoverPayload = {
	source: ChordNode;
	target: ChordNode;
	sourceValue: number;
	targetValue: number;
};

export interface ChordProps extends Omit<React.SVGAttributes<SVGSVGElement>, "children"> {
	/** Nodes (as ring segments). Order matches matrix rows/columns. */
	nodes: ChordNode[];
	/** Square N×N matrix of weights. matrix[i][j] = flow from node i to node j. */
	matrix: number[][];
	/** Pixel size of the rendered SVG (it's square). Default 480. */
	size?: number;
	/** Pixel padding between adjacent ring segments. Default 0.04 (radians, d3 convention). */
	padAngle?: number;
	/** Fired when a ribbon is hovered (or hover ends, with `null`). */
	onChordHover?: (chord: ChordHoverPayload | null) => void;
	/** Fired when a node arc is clicked. */
	onNodeClick?: (node: ChordNode) => void;
}

interface LaidOutArc {
	node: ChordNode;
	depth: number;
	d: string;
	labelX: number;
	labelY: number;
	labelAngle: number;
}

interface LaidOutChord {
	source: ChordNode;
	target: ChordNode;
	sourceValue: number;
	targetValue: number;
	d: string;
	/** Index of the source node — ribbons inherit the source arc's hue
	 * so the eye can trace "where did this flow originate". */
	sourceIdx: number;
}

type D3ChordMod = typeof import("d3-chord");
type D3ShapeMod = typeof import("d3-shape");

function Chord({
	nodes,
	matrix,
	size = 480,
	padAngle = 0.04,
	onChordHover,
	onNodeClick,
	className,
	...rest
}: ChordProps) {
	const [d3c, setD3c] = React.useState<D3ChordMod | null>(null);
	const [d3s, setD3s] = React.useState<D3ShapeMod | null>(null);
	const [importError, setImportError] = React.useState(false);

	React.useEffect(() => {
		let cancelled = false;
		void Promise.all([import("d3-chord"), import("d3-shape")]).then(
			([c, s]) => {
				if (cancelled) return;
				setD3c(c);
				setD3s(s);
			},
			() => {
				if (!cancelled) setImportError(true);
			},
		);
		return () => {
			cancelled = true;
		};
	}, []);

	const laidOut = React.useMemo(() => {
		if (!d3c || !d3s) return null;
		return layout(d3c, d3s, nodes, matrix, size, padAngle);
	}, [d3c, d3s, nodes, matrix, size, padAngle]);

	if (importError) {
		return (
			<div
				data-hex-chord-error
				role="alert"
				className={cn(
					"inline-flex items-center justify-center rounded-md border border-destructive/40 bg-destructive/5 p-3 text-sm text-destructive",
					className,
				)}
				style={{ width: size, height: size }}
			>
				Install <code className="mx-1">d3-chord</code> to view this chord diagram.
			</div>
		);
	}

	if (!laidOut) {
		return (
			<div
				data-hex-chord-loading
				aria-busy="true"
				aria-label="Loading chord diagram"
				className={cn("inline-block bg-muted/20", className)}
				style={{ width: size, height: size }}
			/>
		);
	}

	const { arcs, chords } = laidOut;
	const desc = `Chord diagram with ${nodes.length} node${nodes.length === 1 ? "" : "s"} and ${chords.length} ribbon${chords.length === 1 ? "" : "s"}`;
	const radius = size / 2;

	return (
		<svg
			{...rest}
			data-hex-chord
			role="img"
			width={size}
			height={size}
			viewBox={`${-radius} ${-radius} ${size} ${size}`}
			className={cn("block", className)}
		>
			<title>Chord diagram</title>
			<desc>{desc}</desc>
			<g data-hex-chord-ribbons>
				{chords.map((c, i) => {
					const interactive = Boolean(onChordHover);
					const payload: ChordHoverPayload = {
						source: c.source,
						target: c.target,
						sourceValue: c.sourceValue,
						targetValue: c.targetValue,
					};
					const fireHover = (chord: ChordHoverPayload | null) => onChordHover?.(chord);
					return (
						<path
							key={`${c.source.id}-${c.target.id}-${i}`}
							data-hex-chord-ribbon
							d={c.d}
							className={interactive ? "focus-visible:outline-none focus-visible:outline-2 focus-visible:outline-ring" : undefined}
							fill={pickChartHue(c.sourceIdx)}
							fillOpacity={0.55}
							stroke="hsl(var(--background))"
							strokeWidth={0.5}
							role={interactive ? "button" : undefined}
							tabIndex={interactive ? 0 : undefined}
							aria-label={
								interactive
									? `Flow from ${c.source.label} to ${c.target.label}, value ${c.sourceValue}; reverse value ${c.targetValue}`
									: undefined
							}
							style={{
								cursor: interactive ? "pointer" : undefined,
								transition: "fill-opacity 120ms ease",
							}}
							onMouseEnter={interactive ? () => fireHover(payload) : undefined}
							onMouseLeave={interactive ? () => fireHover(null) : undefined}
							onFocus={interactive ? () => fireHover(payload) : undefined}
							onBlur={interactive ? () => fireHover(null) : undefined}
						/>
					);
				})}
			</g>
			<g data-hex-chord-arcs>
				{arcs.map((a) => {
					const interactive = Boolean(onNodeClick);
					const handleActivate = () => onNodeClick?.(a.node);
					const flip = a.labelAngle > Math.PI / 2 && a.labelAngle < (3 * Math.PI) / 2;
					return (
						<g
							key={a.node.id}
							data-hex-chord-arc
							data-depth={a.depth}
							className={interactive ? "focus-visible:outline-none focus-visible:outline-2 focus-visible:outline-ring" : undefined}
							role={interactive ? "button" : undefined}
							tabIndex={interactive ? 0 : undefined}
							aria-label={interactive ? a.node.label : undefined}
							style={interactive ? { cursor: "pointer" } : undefined}
							onClick={interactive ? handleActivate : undefined}
							onKeyDown={interactive ? (e) => activateOnKey(e, handleActivate) : undefined}
						>
							<path
								d={a.d}
								fill={pickChartHue(a.depth)}
								stroke="hsl(var(--background))"
								strokeWidth={1}
							/>
							<text
								x={a.labelX}
								y={a.labelY}
								textAnchor={flip ? "end" : "start"}
								dy="0.35em"
								transform={
									flip
										? `rotate(${(a.labelAngle * 180) / Math.PI - 270} ${a.labelX} ${a.labelY})`
										: `rotate(${(a.labelAngle * 180) / Math.PI - 90} ${a.labelX} ${a.labelY})`
								}
								fontSize={11}
								fill="hsl(var(--foreground))"
								style={{ pointerEvents: "none" }}
							>
								{a.node.label}
							</text>
						</g>
					);
				})}
			</g>
		</svg>
	);
}

function layout(
	d3c: D3ChordMod,
	d3s: D3ShapeMod,
	nodes: ChordNode[],
	matrix: number[][],
	size: number,
	padAngle: number,
): { arcs: LaidOutArc[]; chords: LaidOutChord[] } {
	// Reserve margin for label text scaled by the longest label, so words
	// like "Americas" / "Manufacturing" don't clip against the SVG edge.
	// 6 px/char + 16 px slack — empirically fits 12-char labels at fontSize 11.
	const longestLabel = nodes.reduce((m, n) => Math.max(m, n.label.length), 0);
	const labelMargin = Math.max(40, longestLabel * 6 + 16);
	const radius = size / 2 - labelMargin;
	const innerRadius = radius - 12;
	const outerRadius = radius;

	// d3.descending lives in d3-array — inline the comparator to avoid pulling
	// another peer dep just for one helper.
	const chordGen = d3c
		.chord()
		.padAngle(padAngle)
		.sortSubgroups((a, b) => (a < b ? 1 : a > b ? -1 : 0));
	const result = chordGen(matrix);

	const arc = d3s.arc().innerRadius(innerRadius).outerRadius(outerRadius);
	// `ribbon()` is exported from d3-chord, not d3-shape.
	const ribbon = d3c.ribbon().radius(innerRadius);

	const arcs: LaidOutArc[] = result.groups.map((g) => {
		const node = nodes[g.index] ?? { id: `_${g.index}`, label: `Set ${g.index}` };
		const midAngle = (g.startAngle + g.endAngle) / 2;
		const labelRadius = outerRadius + 6;
		return {
			node,
			depth: g.index,
			d: arc({ startAngle: g.startAngle, endAngle: g.endAngle, innerRadius, outerRadius }) ?? "",
			labelX: labelRadius * Math.sin(midAngle),
			labelY: -labelRadius * Math.cos(midAngle),
			labelAngle: midAngle,
		};
	});

	// Satisfies @types/d3-chord@3.0.6's `RibbonSubgroup.radius` requirement;
	// runtime ignores per-subgroup radius when the generator's `.radius()`
	// is set, so this spread is purely a typing accommodation.
	const buildRibbonInput = (c: typeof result[number]) => ({
		source: { ...c.source, radius: innerRadius },
		target: { ...c.target, radius: innerRadius },
	});

	const chords: LaidOutChord[] = result
		// Drop chord pairs where both directions have zero flow — d3-chord
		// emits placeholder pairs for them which would otherwise render as
		// invisible-but-event-firing ribbons.
		.filter((c) => c.source.value > 0 || c.target.value > 0)
		.map((c) => ({
			source: nodes[c.source.index] ?? { id: `_${c.source.index}`, label: `Set ${c.source.index}` },
			target: nodes[c.target.index] ?? { id: `_${c.target.index}`, label: `Set ${c.target.index}` },
			sourceValue: c.source.value,
			targetValue: c.target.value,
			d: ribbon(buildRibbonInput(c)) ?? "",
			sourceIdx: c.source.index,
		}));

	return { arcs, chords };
}

function activateOnKey(e: React.KeyboardEvent, fn: () => void): void {
	if (e.key === "Enter" || e.key === " ") {
		e.preventDefault();
		fn();
	}
}

export { Chord };

/**
 * Color conversion utilities for the HSL-triplet token format used across
 * `@hex-core/tokens` themes (`H S% L%`, e.g. `"240 5.9% 10%"` — no `hsl()`
 * wrapper, no commas).
 *
 * The triplet is the round-trip-safe serialization for Hex Core: tokens flow
 * triplet → CSS `hsl(var(--token))` → rendered color, and the ColorPicker
 * component edits triplets directly. Hex/RGB conversions are display
 * adapters, not the source of truth.
 */

/** Parsed HSL components. `h` is degrees (0–360); `s` and `l` are percentages (0–100). */
export interface HslTriplet {
	h: number;
	s: number;
	l: number;
}

/** Parsed RGB components. Each channel is 0–255. */
export interface RgbColor {
	r: number;
	g: number;
	b: number;
}

/**
 * Parse an HSL triplet string into numeric components.
 *
 * Note: malformed input silently coerces to `{0,0,0}` (pure black) rather than
 * returning an error signal. Callers that need to distinguish "user typed
 * black" from "user typed garbage" should validate the input format first.
 * `hexToHslTriplet` returns `null` for malformed hex; this asymmetry is
 * intentional — triplets feed CSS variables where any non-color value would
 * already break rendering.
 *
 * @param triplet - String in the form `"<H> <S>% <L>%"` (e.g. `"240 5.9% 10%"`).
 * @returns Numeric components, or `{0,0,0}` if the input is malformed.
 */
export function parseHslTriplet(triplet: string): HslTriplet {
	const parts = triplet.trim().split(/\s+/);
	return {
		h: Number.parseFloat(parts[0]) || 0,
		s: Number.parseFloat(parts[1]) || 0,
		l: Number.parseFloat(parts[2]) || 0,
	};
}

/**
 * Format HSL components into an HSL triplet string (the canonical token format).
 * @param hsl - Numeric components.
 * @returns Triplet in the form `"<H> <S>% <L>%"`.
 */
export function formatHslTriplet({ h, s, l }: HslTriplet): string {
	// Tolerant integer check: rgbToHsl can produce values like 5.0000000001 due
	// to float arithmetic; format those as "5" rather than "5.0".
	const round = (n: number) =>
		Math.abs(n - Math.round(n)) < 1e-6 ? `${Math.round(n)}` : n.toFixed(1);
	return `${Math.round(h)} ${round(s)}% ${round(l)}%`;
}

/**
 * Convert HSL components to RGB.
 * @param h - Hue (0–360).
 * @param s - Saturation (0–100).
 * @param l - Lightness (0–100).
 * @returns RGB channels (0–255, rounded).
 */
export function hslToRgb(h: number, s: number, l: number): RgbColor {
	const sN = s / 100;
	const lN = l / 100;
	const k = (n: number) => (n + h / 30) % 12;
	const a = sN * Math.min(lN, 1 - lN);
	const f = (n: number) => lN - a * Math.max(-1, Math.min(k(n) - 3, 9 - k(n), 1));
	return {
		r: Math.round(255 * f(0)),
		g: Math.round(255 * f(8)),
		b: Math.round(255 * f(4)),
	};
}

/**
 * Convert RGB components to HSL.
 * @param r - Red (0–255).
 * @param g - Green (0–255).
 * @param b - Blue (0–255).
 * @returns HSL components (h: 0–360, s: 0–100, l: 0–100).
 */
export function rgbToHsl(r: number, g: number, b: number): HslTriplet {
	const rN = r / 255;
	const gN = g / 255;
	const bN = b / 255;
	const max = Math.max(rN, gN, bN);
	const min = Math.min(rN, gN, bN);
	let h = 0;
	let s = 0;
	const l = (max + min) / 2;
	if (max !== min) {
		const d = max - min;
		s = l > 0.5 ? d / (2 - max - min) : d / (max + min);
		if (max === rN) h = (gN - bN) / d + (gN < bN ? 6 : 0);
		else if (max === gN) h = (bN - rN) / d + 2;
		else h = (rN - gN) / d + 4;
		h /= 6;
	}
	return { h: h * 360, s: s * 100, l: l * 100 };
}

/**
 * Convert an HSL triplet to a 6-digit hex string.
 * @param triplet - HSL triplet (e.g. `"240 5.9% 10%"`).
 * @returns Lowercase hex string with leading `#` (e.g. `"#181a1f"`).
 */
export function hslTripletToHex(triplet: string): string {
	const { h, s, l } = parseHslTriplet(triplet);
	const { r, g, b } = hslToRgb(h, s, l);
	const toHex = (n: number) => n.toString(16).padStart(2, "0");
	return `#${toHex(r)}${toHex(g)}${toHex(b)}`;
}

/**
 * Convert a hex string to an HSL triplet.
 * Accepts 3-digit (`#abc`) or 6-digit (`#aabbcc`) hex with optional `#`.
 * @param hex - Hex color string.
 * @returns HSL triplet, or `null` if the input is malformed.
 */
export function hexToHslTriplet(hex: string): string | null {
	const clean = hex.trim().replace(/^#/, "");
	let normalized: string;
	if (/^[0-9a-fA-F]{3}$/.test(clean)) {
		normalized = clean
			.split("")
			.map((c) => c + c)
			.join("");
	} else if (/^[0-9a-fA-F]{6}$/.test(clean)) {
		normalized = clean;
	} else {
		return null;
	}
	const r = Number.parseInt(normalized.slice(0, 2), 16);
	const g = Number.parseInt(normalized.slice(2, 4), 16);
	const b = Number.parseInt(normalized.slice(4, 6), 16);
	return formatHslTriplet(rgbToHsl(r, g, b));
}

import { type ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";

/**
 * Merge class names with Tailwind CSS conflict resolution.
 * @param inputs - Class values (strings, arrays, objects) to merge
 * @returns A single merged class string with Tailwind conflicts resolved
 */
export function cn(...inputs: ClassValue[]) {
	return twMerge(clsx(inputs));
}

const SAFE_URL_SCHEMES = ["http:", "https:", "mailto:"] as const;

/**
 * Allowlist a URL for use as an `<a href>` against untrusted input.
 *
 * Returns the raw string when it's `http(s):` / `mailto:` / a relative
 * URL (no scheme); returns `undefined` otherwise. Defends against
 * `javascript:` / `data:` / `vbscript:` injection from streamed model
 * output or third-party JSON payloads that flow into citation chips.
 *
 * Inside a Markdown render path, `rehype-sanitize` already strips
 * `javascript:` from inline-link hrefs — but it does NOT introspect
 * JSON nested inside attribute values (e.g. `<sources data='[…]'/>`),
 * so the components that consume that data must guard themselves.
 *
 * @param raw - The candidate URL, or `undefined` when none was supplied.
 * @returns The URL when safe to render, otherwise `undefined`.
 */
export function safeUrl(raw: string | undefined): string | undefined {
	if (raw === undefined || raw === "") return undefined;
	// Relative URLs have no scheme — `new URL(relative)` throws without a base,
	// so a thrown URL means either malformed input OR a relative path. Treat
	// "throws + does not contain a colon" as a relative path (safe).
	let parsed: URL;
	try {
		parsed = new URL(raw);
	} catch {
		return raw.includes(":") ? undefined : raw;
	}
	return SAFE_URL_SCHEMES.some((scheme) => scheme === parsed.protocol) ? raw : undefined;
}
